}

export function DialogRoot({ children, defaultOpen = false, onOpenChange, open: openProp }: DialogRootProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen)
  const controlled = openProp !== undefined
  const open = controlled ? openProp : uncontrolledOpen
  const controlledRef = useRef(controlled)
  const onOpenChangeRef = useRef(onOpenChange)
  const openRef = useRef(open)
  const reactId = useId()
  const layerId = useMemo(() => Symbol('dialog-layer'), [])

  useIsomorphicLayoutEffect(() => {
    controlledRef.current = controlled
    onOpenChangeRef.current = onOpenChange
    openRef.current = open
  }, [controlled, onOpenChange, open])

  const setOpen = useCallback((nextOpen: boolean) => {
    if (nextOpen === openRef.current) return
    if (!controlledRef.current) setUncontrolledOpen(nextOpen)
    onOpenChangeRef.current?.(nextOpen)
  }, [])

  const value = useMemo<DialogContextValue>(
    () => ({
      contentId: `${reactId}-content`,
      descriptionId: `${reactId}-description`,
      layerId,
      open,
      setOpen,
      titleId: `${reactId}-title`,
    }),
    [layerId, open, reactId, setOpen],
  )

  return <DialogContext.Provider value={value}>{children}</DialogContext.Provider>
}

